import { useState } from "react";
import { useNavigate, useParams, useSearchParams } from "react-router-dom";
import { isDatasetId, type DatasetId } from "../../entities/dataset";
import { isDatasetVersionId, type DatasetVersionId } from "../../entities/dataset-version";
import { isDomainError } from "../../shared/api/domain-error";
import { useCapabilities } from "../../shared/auth/use-capabilities";
import { useAsyncJob } from "../../shared/jobs/use-async-job";
import {
  useApproveReviewMutation,
  useCreateVersionDiffJobMutation,
  useDeletionPreflightMutation,
  useReturnReviewMutation,
  useReviewChecksMutation,
  useVersionBootstrapQuery,
  useVersionEpisodesQuery,
  useVersionManifestQuery,
} from "../../features/datasets/api";
import { ConfirmDialog } from "../../features/datasets/components/ConfirmDialog";
import { RegionState } from "../../features/datasets/components/RegionState";
import { datasetRegionStateForError } from "../../features/datasets/components/error-state";
import { buildSuccessorDraftPendingLink } from "../../features/datasets/pending-links";
import { canRunReviewMutation, getReviewStatePolicy } from "../../features/datasets/review-state-machine";
import { routes, type VersionDetailTab } from "../../features/datasets/routing";
import versionDetailQueryCodec from "./query-codec";
import "../../features/datasets/components/datasets.css";

const invalidDataset = "dataset_invalid" as DatasetId;
const invalidVersion = "version_invalid" as DatasetVersionId;
const tabs: readonly { id: VersionDetailTab; label: string }[] = [
  { id: "revisions", label: "Episodes" },
  { id: "changes", label: "变更" },
  { id: "review", label: "Review" },
  { id: "manifest", label: "Manifest" },
  { id: "schema", label: "Schema" },
  { id: "capacity", label: "容量" },
  { id: "exports", label: "导出" },
];

type Severity = "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";

function nextIdempotencyKey(prefix: string): string {
  return globalThis.crypto?.randomUUID?.() ?? `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function JobStatus({ jobId }: { jobId: string }) {
  const job = useAsyncJob(jobId);
  if (job.isPending) return <RegionState state="first-loading" title="任务已接受" />;
  if (job.isError) {
    return <RegionState state={datasetRegionStateForError(job.error)} message={job.error instanceof Error ? job.error.message : undefined} onRetry={() => void job.refetch()} />;
  }
  return (
    <section className="dataset-band">
      <h2>异步任务</h2>
      <p><code>{jobId}</code> · {job.data.status} · {job.connectionStatus}</p>
      {job.data.status === "FAILED" ? <RegionState state="partial-error" message="任务失败；版本事实未被前端乐观改写。" /> : null}
    </section>
  );
}

export function VersionDetailPage() {
  const raw = useParams();
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const search = versionDetailQueryCodec.parse(params);
  const capabilities = useCapabilities();
  const valid = isDatasetId(raw.datasetId) && isDatasetVersionId(raw.versionId);
  const datasetId = valid ? raw.datasetId as DatasetId : invalidDataset;
  const versionId = valid ? raw.versionId as DatasetVersionId : invalidVersion;
  const bootstrap = useVersionBootstrapQuery(datasetId, versionId, valid && capabilities.has("dataset_version.read"));
  const episodes = useVersionEpisodesQuery(
    datasetId,
    versionId,
    { ...search, snapshotToken: bootstrap.data?.snapshotToken },
    valid && Boolean(bootstrap.data) && capabilities.has("episode.read") && search.tab === "revisions",
  );
  const manifest = useVersionManifestQuery(
    datasetId,
    versionId,
    { after: search.after, before: search.before, limit: search.limit },
    valid && search.tab === "manifest" && capabilities.has("dataset_version.read"),
  );
  const checks = useReviewChecksMutation();
  const approveMutation = useApproveReviewMutation();
  const returnMutation = useReturnReviewMutation();
  const preflight = useDeletionPreflightMutation();
  const diffJob = useCreateVersionDiffJobMutation();

  const [approveOpen, setApproveOpen] = useState(false);
  const [returnOpen, setReturnOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [diffOpen, setDiffOpen] = useState(false);
  const [approveIntentKey, setApproveIntentKey] = useState<string | null>(null);
  const [returnIntentKey, setReturnIntentKey] = useState<string | null>(null);
  const [deleteIntentKey, setDeleteIntentKey] = useState<string | null>(null);
  const [diffIntentKey, setDiffIntentKey] = useState<string | null>(null);
  const [selectedRevisionId, setSelectedRevisionId] = useState("");
  const [selectedStreamId, setSelectedStreamId] = useState("");
  const [note, setNote] = useState("");
  const [severity, setSeverity] = useState<Severity>("HIGH");
  const [findingType, setFindingType] = useState("");
  const [startNs, setStartNs] = useState("0");
  const [endNs, setEndNs] = useState("1");
  const [jobId, setJobId] = useState<string | null>(null);
  const [compareTo, setCompareTo] = useState("");

  if (!valid) {
    return <main className="dataset-page" data-page-id="P07"><RegionState state="not-found" message="必须提供稳定 Dataset ID 与 Version ID；latest/current 不被接受。" /></main>;
  }
  if (capabilities.loading || bootstrap.isPending) return <main className="dataset-page"><RegionState state="first-loading" /></main>;
  if (capabilities.failed || !capabilities.has("dataset_version.read")) return <main className="dataset-page"><RegionState state="forbidden" /></main>;
  if (bootstrap.isError) {
    return <main className="dataset-page"><RegionState state={datasetRegionStateForError(bootstrap.error)} message={bootstrap.error instanceof Error ? bootstrap.error.message : undefined} onRetry={() => void bootstrap.refetch()} /></main>;
  }

  const data = bootstrap.data;
  const version = data.version;
  const policy = getReviewStatePolicy(version.status, version.deliveryStatus);
  const reviewAction = data.allowedActions.find((action) => action.action === "REVIEW_VERSION");
  const canReturn = capabilities.has("dataset_version.review") && reviewAction?.allowed === true && canRunReviewMutation(policy, "RETURN");
  const canApprove = canReturn && capabilities.has("dataset_version.publish") && canRunReviewMutation(policy, "APPROVE");
  const target = checks.data?.eligible_targets.find((item) => item.output_revision_id === selectedRevisionId);
  const stream = target?.streams.find((item) => item.episode_stream_id === selectedStreamId);
  const catalogType = checks.data?.finding_catalog.finding_types.find((item) => item.code === findingType);
  const allowedSeverities = catalogType?.allowed_severities ?? [];
  const trimmedNote = note.trim();
  const noteValid = Boolean(checks.data) &&
    trimmedNote.length >= (checks.data?.finding_catalog.note_min_length ?? 1) &&
    trimmedNote.length <= (checks.data?.finding_catalog.note_max_length ?? 0);
  const rangeValid = Boolean(stream) && /^\d+$/.test(startNs) && /^\d+$/.test(endNs) &&
    BigInt(startNs) >= BigInt(stream?.t_start_ns ?? "0") &&
    BigInt(endNs) <= BigInt(stream?.t_end_ns ?? "0") &&
    BigInt(startNs) < BigInt(endNs);
  const returnFormValid = Boolean(
    returnIntentKey && target && stream && catalogType &&
    allowedSeverities.includes(severity) && noteValid && rangeValid,
  );
  const reviewError = approveMutation.error ?? returnMutation.error;

  const runChecks = () => checks.mutate(
    { datasetId, versionId, etag: version.etag },
    {
      onSuccess: (result) => {
        const firstTarget = result.eligible_targets[0];
        const firstStream = firstTarget?.streams[0];
        const firstType = result.finding_catalog.finding_types[0];
        const firstSeverity = firstType?.allowed_severities[0];
        setSelectedRevisionId(firstTarget?.output_revision_id ?? "");
        setSelectedStreamId(firstStream?.episode_stream_id ?? "");
        setStartNs(firstStream?.t_start_ns ?? "0");
        setEndNs(firstStream?.t_end_ns ?? "1");
        setFindingType(firstType?.code ?? "");
        if (firstSeverity) setSeverity(firstSeverity);
        setApproveOpen(false);
        setReturnOpen(false);
        setApproveIntentKey(null);
        setReturnIntentKey(null);
      },
    },
  );

  const openApprove = () => {
    setApproveIntentKey(nextIdempotencyKey("review-approve"));
    setApproveOpen(true);
  };

  const confirmApprove = () => {
    if (!checks.data || !approveIntentKey) return;
    approveMutation.mutate({
      datasetId,
      versionId,
      etag: version.etag,
      idempotencyKey: approveIntentKey,
      command: { expected_status: "REVIEWING", review_token: checks.data.review_token },
    }, {
      onSuccess: (result) => {
        setApproveOpen(false);
        setApproveIntentKey(null);
        setJobId(result.jobId);
        void bootstrap.refetch();
      },
    });
  };

  const openReturn = () => {
    setReturnIntentKey(nextIdempotencyKey("review-return"));
    setReturnOpen(true);
  };

  const confirmReturn = () => {
    if (!checks.data || !target || !stream || !returnIntentKey || !returnFormValid) return;
    returnMutation.mutate({
      datasetId,
      versionId,
      expectedSourceDraftId: checks.data.source_draft_id,
      etag: version.etag,
      idempotencyKey: returnIntentKey,
      command: {
        expected_status: "REVIEWING",
        review_token: checks.data.review_token,
        finding_catalog_version: checks.data.finding_catalog.version,
        findings: [{
          output_revision_id: target.output_revision_id,
          episode_stream_id: stream.episode_stream_id,
          start_ns: startNs,
          end_ns: endNs,
          finding_type: findingType,
          severity,
          note: trimmedNote,
        }],
      },
    }, {
      onSuccess: () => {
        setReturnOpen(false);
        setReturnIntentKey(null);
        void bootstrap.refetch();
      },
    });
  };

  const reviewConflict = reviewError && isDomainError(reviewError) &&
    (reviewError.code === "VERSION_CONFLICT" || reviewError.code === "PRECONDITION_FAILED");

  return (
    <main className="dataset-page" data-page-id="P07">
      <header className="dataset-resource-header">
        <div><p className="dataset-eyebrow">Immutable version</p><h1>{version.displayVersion}</h1><p><code>{datasetId}</code> / <code>{versionId}</code></p></div>
        <div className="dataset-actions">
          <span className={`dataset-status dataset-status--${version.status.toLowerCase()}`}>{version.status}</span>
          <button type="button" className="dataset-button dataset-button--danger" onClick={() => { setDeleteIntentKey(nextIdempotencyKey("version-delete-preflight")); setDeleteOpen(true); }}>删除预检</button>
        </div>
      </header>
      <nav className="dataset-tabs" aria-label="版本详情分区">
        {tabs.map((tab) => <button type="button" className="dataset-tab" role="tab" aria-selected={search.tab === tab.id} key={tab.id} onClick={() => navigate(routes.versionDetail.build({ datasetId, versionId, tab: tab.id }))}>{tab.label}</button>)}
      </nav>

      <section className="dataset-band">
        <div className="dataset-band-heading"><div><h2>版本概要</h2><p>Snapshot 与 operational revision 分离，均绑定固定 Version。</p></div></div>
        <dl className="dataset-metrics">
          <div className="dataset-metric"><dt>类型</dt><dd>{version.kind}</dd></div>
          <div className="dataset-metric"><dt>状态</dt><dd>{version.status}</dd></div>
          <div className="dataset-metric"><dt>Delivery</dt><dd>{version.deliveryStatus ?? "—"}</dd></div>
          <div className="dataset-metric"><dt>Snapshot</dt><dd title={data.snapshotToken}>{data.snapshotToken.slice(0, 12)}…</dd></div>
          <div className="dataset-metric"><dt>Operational</dt><dd>{data.operationalRevision}</dd></div>
        </dl>
      </section>
      {policy.unknownEnum ? <RegionState state="unknown-enum" message={policy.reason} /> : null}

      {search.tab === "revisions" ? (
        <section className="dataset-band">
          <h2>Episodes / Revisions</h2>
          {episodes.isPending ? <RegionState state="first-loading" /> : episodes.isError ? <RegionState state={datasetRegionStateForError(episodes.error)} onRetry={() => void episodes.refetch()} /> : episodes.data.items.length === 0 ? <RegionState state="empty" /> : (
            <div className="dataset-table-scroll"><table className="dataset-table"><thead><tr><th>Episode</th><th>Revision</th><th>Included</th><th>Review</th><th /></tr></thead><tbody>{episodes.data.items.map((episode) => <tr key={episode.episodeId}><td>{episode.episodeId}</td><td>{episode.selectedRevisionId}</td><td>{episode.included ? "是" : "否"}</td><td>{episode.reviewStatus} · {episode.reviewFindingCount}</td><td><button type="button" className="dataset-link" onClick={() => navigate(routes.episodeViewer.build({ datasetId, versionId, episodeId: episode.episodeId, returnTo: routes.versionDetail.build({ datasetId, versionId, tab: "revisions" }) }))}>只读 Viewer</button></td></tr>)}</tbody></table></div>
          )}
        </section>
      ) : null}

      {search.tab === "review" ? (
        <section className="dataset-band">
          <div className="dataset-band-heading">
            <div><h2>Review 决定与 Findings</h2><p>P07 是唯一 Review mutation Owner；Finding 是不可变事实，不是 ManualIssue。</p></div>
            <div className="dataset-actions">
              <button type="button" className="dataset-button dataset-button--secondary" disabled={!canReturn || checks.isPending} onClick={runChecks}>{checks.isPending ? "预检中…" : "运行 Review 预检"}</button>
              <button type="button" className="dataset-button" disabled={!canApprove || !checks.data || checks.data.blockers.length > 0} onClick={openApprove}>通过</button>
              <button type="button" className="dataset-button dataset-button--danger" disabled={!canReturn || !checks.data} onClick={openReturn}>退回</button>
            </div>
          </div>
          {!canReturn ? <RegionState state={policy.unknownEnum ? "unknown-enum" : "feature-unavailable"} message={reviewAction?.blockedReasons.map((reason) => reason.message).join("；") || policy.reason} /> : null}
          {canReturn && !capabilities.has("dataset_version.publish") ? <RegionState state="feature-unavailable" title="通过操作不可用" message="Approve 还需要独立的 dataset_version.publish capability；Return 不受此项影响。" /> : null}
          {checks.isError ? <RegionState state={datasetRegionStateForError(checks.error)} message={checks.error instanceof Error ? checks.error.message : undefined} onRetry={runChecks} /> : null}
          {checks.data ? <div><p>Catalog <code>{checks.data.finding_catalog.version}</code> · Token 到期 {new Date(checks.data.review_token_expires_at).toLocaleString()}</p>{checks.data.blockers.length ? <RegionState state="feature-unavailable" title="Approve 被阻断" message={`${checks.data.blockers.map((item) => item.message).join("；")}；Return 仍可提交合法 Finding。`} /> : null}</div> : null}
          {returnMutation.isSuccess && !data.returnLineage ? <RegionState state="refreshing" title="正在核对退回事实" message="完整命令已返回；正在重读固定 Version，确认 Decision、Findings 与 successor lineage。" /> : null}
          {data.returnLineage ? (
            <div className="dataset-blocked-reasons">
              <h3>不可变退回事实</h3>
              <p>Decision <code>{data.returnLineage.reviewDecisionId}</code> · Version <code>{data.returnLineage.returnedFromVersionId}</code></p>
              <p>Findings: {data.returnLineage.reviewFindingIds.map((id) => <code key={id}>{id} </code>)}</p>
              <button type="button" className="dataset-button" onClick={() => navigate(buildSuccessorDraftPendingLink(data.returnLineage!.successorDraftId))}>继续返工</button>
            </div>
          ) : null}
        </section>
      ) : null}

      {search.tab === "manifest" ? <section className="dataset-band"><h2>Manifest 摘要</h2><p>原文不进入遥测、错误日志或 query key。</p>{manifest.isPending ? <RegionState state="first-loading" /> : manifest.isError ? <RegionState state={datasetRegionStateForError(manifest.error)} onRetry={() => void manifest.refetch()} /> : <><p><code>{manifest.data.manifest.manifest_id}</code> · SHA-256 {manifest.data.manifest.sha256}</p><div className="dataset-table-scroll"><table className="dataset-table"><thead><tr><th>Entry</th><th>Episode</th><th>Role</th><th>Bytes</th><th>SHA-256</th></tr></thead><tbody>{manifest.data.items.map((item) => <tr key={item.entry_id}><td>{item.entry_id}</td><td>{item.episode_id}</td><td>{item.role}</td><td>{item.size_bytes}</td><td><code>{item.sha256.slice(0, 16)}…</code></td></tr>)}</tbody></table></div></>}</section> : null}
      {search.tab === "changes" ? <RegionState state="feature-unavailable" message="Diff 必须显式选择 compareTo，绝不解析 latest/current。" /> : null}
      {search.tab === "schema" ? <RegionState state="feature-unavailable" message="Schema 区域绑定当前 snapshot token，失败不影响其他区域。" /> : null}
      {search.tab === "capacity" ? <RegionState state="feature-unavailable" message="Required 与 operational storage 是两个独立事实源。" /> : null}
      {search.tab === "exports" ? (
        <section className="dataset-band">
          <h2>导出 / Diff 异步任务</h2>
          <p>导出下载授权仍未冻结；当前仅提供合同已冻结的 Version Diff AsyncJob。</p>
          <label>比较 Version ID<input value={compareTo} onChange={(event) => setCompareTo(event.target.value)} /></label>
          <button type="button" className="dataset-button" disabled={!isDatasetVersionId(compareTo) || compareTo === versionId || diffJob.isPending} onClick={() => { setDiffIntentKey(nextIdempotencyKey("version-diff")); setDiffOpen(true); }}>确认创建 Diff Job</button>
          {diffJob.isError ? <RegionState state={datasetRegionStateForError(diffJob.error)} message={diffJob.error instanceof Error ? diffJob.error.message : undefined} /> : null}
          {jobId ? <JobStatus jobId={jobId} /> : null}
        </section>
      ) : null}

      {reviewConflict ? <RegionState state="conflict" message="服务端版本已变化。Finding 输入与原幂等键已保留；刷新事实后必须重新预检和确认。" requestId={isDomainError(reviewError) ? reviewError.requestId : null} onRetry={() => void bootstrap.refetch()} /> : reviewError ? <RegionState state={datasetRegionStateForError(reviewError)} message={reviewError instanceof Error ? reviewError.message : undefined} /> : null}

      <ConfirmDialog open={approveOpen} title="通过固定 Version" resourceId={versionId} description="通过只创建不可变 APPROVED Decision 与物化 Job；Job 成功不代表 Version 已 READY。" impact={["当前 Version 暂时保持 REVIEWING", "创建不可变 Review Decision", "启动 Manifest/物化异步任务"]} blockedReasons={checks.data?.blockers.map((item) => item.message)} confirmLabel="确认通过并启动任务" confirmDisabled={!approveIntentKey || !canApprove} submitting={approveMutation.isPending} onConfirm={confirmApprove} onCancel={() => { if (!approveMutation.isPending) { setApproveOpen(false); setApproveIntentKey(null); } }} />

      <ConfirmDialog open={returnOpen} title="退回固定 Version" resourceId={versionId} description="服务端将在一次事务中创建不可变 Decision、至少一条 Finding、RETURNED 终态和新 ID 的后继 Draft。" impact={["当前 Version 进入终态 RETURNED", "Review Decision 与 Finding 永久不可变", "创建唯一 successor Draft；页面先留在 P07 核对事实"]} confirmLabel="确认原子退回" confirmDisabled={!returnFormValid} submitting={returnMutation.isPending} onConfirm={confirmReturn} onCancel={() => { if (!returnMutation.isPending) { setReturnOpen(false); setReturnIntentKey(null); } }}>
        {checks.data?.blockers.length ? <div className="dataset-review-note"><strong>Approve 阻断不阻止 Return</strong><ul>{checks.data.blockers.map((item) => <li key={item.code}>{item.message}</li>)}</ul></div> : null}
        <label>输出 Revision<select aria-label="输出 Revision" value={selectedRevisionId} onChange={(event) => { const next = checks.data?.eligible_targets.find((item) => item.output_revision_id === event.target.value); const nextStream = next?.streams[0]; setSelectedRevisionId(event.target.value); setSelectedStreamId(nextStream?.episode_stream_id ?? ""); setStartNs(nextStream?.t_start_ns ?? "0"); setEndNs(nextStream?.t_end_ns ?? "1"); }}>{checks.data?.eligible_targets.map((item) => <option key={item.output_revision_id} value={item.output_revision_id}>{item.output_revision_id} · {item.episode_id}</option>)}</select></label>
        <label>Episode Stream<select aria-label="Episode Stream" value={selectedStreamId} onChange={(event) => { const next = target?.streams.find((item) => item.episode_stream_id === event.target.value); setSelectedStreamId(event.target.value); setStartNs(next?.t_start_ns ?? "0"); setEndNs(next?.t_end_ns ?? "1"); }}>{target?.streams.map((item) => <option key={item.episode_stream_id} value={item.episode_stream_id}>{item.channel_path} · {item.episode_stream_id}</option>)}</select></label>
        <label>Finding 类型<select aria-label="Finding 类型" value={findingType} onChange={(event) => { const next = checks.data?.finding_catalog.finding_types.find((item) => item.code === event.target.value); setFindingType(event.target.value); const nextSeverity = next?.allowed_severities[0]; if (nextSeverity) setSeverity(nextSeverity); }}>{checks.data?.finding_catalog.finding_types.map((item) => <option key={item.code} value={item.code}>{item.label} · {item.code}</option>)}</select></label>
        <label>严重级别<select aria-label="严重级别" value={severity} onChange={(event) => setSeverity(event.target.value as Severity)}>{allowedSeverities.map((item) => <option key={item} value={item}>{checks.data?.finding_catalog.severities.find((entry) => entry.code === item)?.label ?? item}</option>)}</select></label>
        <label>开始 ns<input inputMode="numeric" value={startNs} onChange={(event) => setStartNs(event.target.value)} /></label>
        <label>结束 ns<input inputMode="numeric" value={endNs} onChange={(event) => setEndNs(event.target.value)} /></label>
        <label>说明<textarea required minLength={checks.data?.finding_catalog.note_min_length} maxLength={checks.data?.finding_catalog.note_max_length} value={note} onChange={(event) => setNote(event.target.value)} /></label>
      </ConfirmDialog>

      <ConfirmDialog open={deleteOpen} title="Version 删除预检" resourceId={versionId} description="预检只返回影响与阻断事实；v1alpha1 没有可执行删除端点。" impact={["固定 Version 与 Revision 引用", "Manifest 和存储对象", "Review Decision、Finding 与审计保护"]} confirmLabel="运行不可执行预检" confirmDisabled={!deleteIntentKey} submitting={preflight.isPending} onConfirm={() => { if (!deleteIntentKey) return; preflight.mutate({ datasetId, versionId, etag: version.etag, reason: "Inspect deletion impact only", idempotencyKey: deleteIntentKey }, { onSuccess: () => { setDeleteOpen(false); setDeleteIntentKey(null); } }); }} onCancel={() => { if (!preflight.isPending) { setDeleteOpen(false); setDeleteIntentKey(null); } }} />
      {preflight.data ? <RegionState state="feature-unavailable" title="预检完成，禁止执行" message={`domain_clear=${String(preflight.data.domain_clear)}；${preflight.data.blocked_reasons.map((item) => item.message).join("；") || "即使无领域阻断，token 也不可执行"}`} /> : preflight.isError ? <RegionState state={datasetRegionStateForError(preflight.error)} message={preflight.error instanceof Error ? preflight.error.message : undefined} /> : null}

      <ConfirmDialog open={diffOpen} title="创建 Version Diff Job" resourceId={versionId} description="异步任务只比较两个固定 Version；不会把当前页面乐观标记为完成。" impact={[`对比目标 ${compareTo}`, "创建一个可重放的 AsyncJob", "只在 Job 终态后读取结果"]} confirmLabel="确认创建 Diff Job" confirmDisabled={!diffIntentKey || !isDatasetVersionId(compareTo) || compareTo === versionId} submitting={diffJob.isPending} onConfirm={() => { if (!diffIntentKey || !isDatasetVersionId(compareTo) || compareTo === versionId) return; diffJob.mutate({ datasetId, versionId, compareTo, snapshotToken: data.snapshotToken, etag: version.etag, idempotencyKey: diffIntentKey }, { onSuccess: (createdJobId) => { setJobId(createdJobId); setDiffOpen(false); setDiffIntentKey(null); } }); }} onCancel={() => { if (!diffJob.isPending) { setDiffOpen(false); setDiffIntentKey(null); } }} />
    </main>
  );
}

export default VersionDetailPage;
